from docx.enum.text import WD_ALIGN_PARAGRAPH
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..")); R = os.path.join(ROOT, "results"); M = json.load(open(f"{R}/metrics.json"))
fm = M["forecasters"]; h = M["hyp"]; vc = M["vc"]["estimate"]; vci = M["vc"]["ci95"]; tot = vc["sigma2_journal"] + vc["sigma2_year"] + vc["sigma2_resid"]
g = {(r["T"], r["threshold"]): r for r in M["guarantee"]}; e7 = M["e7"]["bootstrap"]; ab = M["ablation"]; ex = M["e9"]; e8 = M["e8"]; dr = M["drift"]; rec = M["recent"]; ft = {r['field']: r for r in M['post']['field_table']}
con = M["contrasts"]; st = {r["stratum"]: r for r in M["strata"]}; sens = M["sensitivity"]; hb = M["high_bin_72"]; vce = M["vc_ext"]["estimate"]; vcie = M["vc_ext"]["ci95"]
pc = lambda x, d=1: f"{100*x:.{d}f}%"
ratio80 = 2.718281828 ** fm["F0"]["width80"]
doc = Document()
for s in doc.sections: s.left_margin = s.right_margin = Cm(2.5); s.top_margin = s.bottom_margin = Cm(2.5)
st_ = doc.styles["Normal"]; st_.font.name = "Times New Roman"; st_.font.size = Pt(11); st_.paragraph_format.line_spacing = 1.5
for n in ("Heading 1", "Heading 2"):
    doc.styles[n].font.name = "Times New Roman"; doc.styles[n].font.color.rgb = None; doc.styles[n].font.bold = True
doc.styles["Heading 1"].font.size = Pt(13); doc.styles["Heading 2"].font.size = Pt(11.5)
def P(text, bold=False, italic=False, align=None, size=None, space=6):
    p = doc.add_paragraph(); r = p.add_run(text); r.bold = bold; r.italic = italic
    if size: r.font.size = Pt(size)
    if align == "c": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_after = Pt(space); return p
def H(t, l=1): doc.add_heading(t, level=l)
def table(df, caption, widths=None, size=8.5):
    P(caption, bold=True, size=10, space=2)
    t = doc.add_table(rows=1, cols=len(df.columns)); t.style = "Table Grid"
    for i, c in enumerate(df.columns):
        cell = t.rows[0].cells[i]; cell.text = ""; r = cell.paragraphs[0].add_run(str(c)); r.bold = True; r.font.size = Pt(size)
    for _, row in df.iterrows():
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""; r = cells[i].paragraphs[0].add_run(v if isinstance(v, str) else (f"{v:.3f}" if isinstance(v, float) else str(v))); r.font.size = Pt(size)
    for row in t.rows:
        for c in row.cells:
            for p in c.paragraphs: p.paragraph_format.line_spacing = 1.0; p.paragraph_format.space_after = Pt(0)
    doc.add_paragraph().paragraph_format.space_after = Pt(4)
def fig(paths, caption, w=3.0):
    if isinstance(paths, str): paths = [paths]
    if len(paths) == 1: doc.add_picture(paths[0], width=Inches(w * (2 if w < 4 else 1) if False else 5.8 if w > 4 else w * 1.6)); doc.paragraphs[-1].alignment = WD_ALIGN_PARAGRAPH.CENTER
    else:
        t = doc.add_table(rows=1, cols=len(paths))
        for i, p in enumerate(paths):
            c = t.rows[0].cells[i]; c.paragraphs[0].add_run().add_picture(p, width=Inches(3.0)); c.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    P(caption, size=9.5, space=10)
F = f"{ROOT}/results/figures/"
# ------------------------------------------------------------------ title page
P("How well do a journal's past turnaround times predict the next paper's? A pre-specified out-of-time evaluation across 800 journals", bold=True, align="c", size=15, space=10)
P("[Author names, affiliations, ORCID iDs and corresponding-author details to be supplied by the authors]", italic=True, align="c", space=10)
WC_PLACEHOLDER = P("Manuscript prepared for submission to Accountability in Research (best-available target; see cover letter). Word count: WC.", italic=True, align="c", size=9, space=14)
H("Abstract")
P(f"Authors, funders and evaluators routinely use a journal's stated or past turnaround as a forecast of how long a newly submitted paper will take, but such statistics have not been tested out of time. "
  f"We pre-specified an evaluation using publisher-deposited submission and acceptance dates for {M['n_records']:,} research articles from {M['n_journals']} Springer Nature, Wiley and Taylor & Francis journals. "
  f"At two forecast origins (1 January 2023 and 2024), forecasts built only from papers already visible were scored against all {M['n_target_papers']:,} papers submitted to {M['n_journals_forecast']} journals in the following six months, using pinball loss, interval coverage and event-probability scores. "
  f"Journal identity explained {pc(vc['sigma2_journal']/tot)} (95% CI {pc(vci['icc_journal'][0])}–{pc(vci['icc_journal'][1])}) of the variance of log acceptance time; {pc(vc['sigma2_resid']/tot)} lay between articles within a journal-year. "
  f"Journal-specific empirical forecasts lowered pinball loss by {pc(fm['F0']['skill'])} relative to publisher-pooled forecasts, yet nominal 80% intervals covered only {pc(0.8+fm['F0']['cov80_minus'])} of later papers and the average interval spanned a five-fold range of days. "
  f"Parametric and shrinkage forecasters did not improve on simple empirical quantiles; a post-hoc diagnostic indicated that roughly half of the under-coverage arises because slow papers are not yet visible. Only {pc(g[(72,0.5)]['share'])} of journal-origins had at least half of their papers accepted within 72 days and {pc(g[(72,0.8)]['share'])} at least 80%; when past data indicated at least 80%, {pc(hb['realised'],0)} was realised. "
  f"Author count and reference count improved forecasts by about {pc(e7['rel_gain_vs_ctrl'],0)}. A check on {int(ex['F0']['n_journal_origins'])} journal-origins from a non-random set of PubMed-indexed journals outside the frame gave a similar picture, with a smaller coverage shortfall ({(ex['F0']['cov80']-0.8)*100:+.1f} points). "
  "Journal-level turnaround statistics are informative but should be reported and used as wide, drifting distributions rather than point guarantees. Conclusions are conditional on acceptance and on publisher-defined submission dates.", space=8)
P("Keywords: peer review; publication delay; acceptance time; probabilistic forecasting; scholarly publishing; research evaluation", italic=True)
# ------------------------------------------------------------------ introduction
H("1. Introduction")
P("Time to publication is a material cost of choosing a journal. Delays affect careers, funding decisions and the currency of findings (Powell, 2016; Ellison, 2002), and journals increasingly advertise speed. Previous work has documented how long review and publication take: Björk and Solomon (2013) sampled 2,700 papers from 135 journals and found large differences between fields, with most of the variance in submission-to-acceptance time lying among articles within a journal; Huisman and Smits (2017) surveyed authors; Mrowinski et al. (2016) modelled the stages of one journal's editorial workflow; and a systematic review found that reported submission-to-publication times in biomedical journals vary widely and are defined inconsistently (Andersen et al., 2021). Bilalli et al. (2021) showed, for ten computer-science journals, that publisher-reported averages can differ greatly from values computed from article metadata. Turnaround is also not stationary: it fell sharply for COVID-19 papers (Horbach, 2020), and has lengthened in economics (Ellison, 2002) and accounting (Argilés-Bosch et al., 2023).")
P("What these studies do not provide is a test of the use to which turnaround statistics are put: as a forecast for a paper that has not yet been submitted. A forecast must use only information available when the choice is made, must be scored against later outcomes, and should convey uncertainty. The question matters because authors act on quantities such as a journal's median or ‘average days to acceptance’, and because evaluative or funder policies sometimes require a stated maximum time to acceptance. A concurrent registered bibliometric study of about 6.6 million PubMed-indexed articles plans a machine-learning model of acceptance lag with a random train–test split (Dianovics et al., 2026); a random split mixes past and future and so does not address forecasting.")
P("We therefore ask five questions. RQ1: how much of the variance of acceptance time lies between journals, between years within journals, and between articles? RQ2: how accurate and calibrated are out-of-time forecasts of a journal's acceptance-time distribution built from its visible past, and which simple estimator is best? RQ3: how large is drift relative to sampling noise? RQ4: how often does past evidence support a claim that a given share of papers is accepted within 72 days, and how reliable are such claims out of time? RQ5: do article features observable around submission improve on the journal-level forecast? RQ1 extends the variance partition of Björk and Solomon (2013) to a larger and more recent dataset; RQ2–RQ5 are, as far as our searches (which did not include reading every full text) could establish, not addressed in earlier work. The study is empirical meta-research. It makes no causal claims and does not propose new theory.")
# ------------------------------------------------------------------ methods
H("2. Methods")
H("2.1 Pre-specification and transparency", 2)
P("The protocol (frame, cleaning rules, cohorts, forecasters, metrics, seven confirmatory contrasts and five confirmatory hypotheses) was committed to the project's git history before any forecast error was computed (protocol v1.0, 20 October 2026). This is a pre-specification by the analyst, not a registered report: there is no external registry entry or independent time stamp. Ten amendments, documentation corrections and post-hoc additions (D1–D10) are logged in the repository, including three that came after results were seen (D5–D7, D10 exploratory). Hypothesis thresholds were set in advance; unsupported hypotheses are reported as such. A first research direction (duplicate contamination in tabular machine-learning benchmarks) was abandoned before any model was run after a prior-art search found overlapping work; the audit trail is in the repository.")
H("2.2 Data", 2)
P(f"Article-level submission (‘received’) and acceptance dates are deposited in Crossref metadata by Springer Nature, Wiley and Taylor & Francis. For each of these three members we took the 1,000 ISSNs with most journal articles published in 2023, merged print and online ISSNs ({M['frame_raw_journals']:,} journals), and kept journals in which at least 80% of 40 random 2023 records carried both dates and the estimated number of dated 2023 articles was between 150 and 3,000. All {M['frame_journals']} resulting journals were downloaded (census of the frame; publication dates 1 January 2021 to 20 October 2026; data cutoff 20 October 2026). The frame excludes small and very large journals and all publishers that do not deposit dates (notably Elsevier and IEEE). The estimand is D, the number of days from received to accepted, conditional on acceptance; rejected papers are not observable.")
P(f"Records were cleaned with rules fixed in advance: duplicate DOIs ({M['cleaning']['C6_duplicate_doi_removed']:,}); D < 1 or D > 1,460 days ({M['cleaning']['C2_D_out_of_range']:,}); acceptance more than seven days after first online publication ({M['cleaning']['C3_accepted_after_pub']:,}); and non-research items by title pattern or fewer than five references ({M['cleaning']['C5_nonresearch']:,}). Of {M['n_raw_dated']:,} dated records, {M['n_records']:,} remained ({M['n_journals']} journals). Median D was {M['D_quantiles']['0.5']:.0f} days (5th–95th percentiles {M['D_quantiles']['0.05']:.0f}–{M['D_quantiles']['0.95']:.0f}); {pc(M['share_D_le_72'])} of papers were accepted within 72 days.")
H("2.3 Forecasting task", 2)
P("Forecast origins were 1 January 2023 and 1 January 2024 (Figure 1). At an origin, the information set of an author contains papers that were first online before the origin and had already been received and accepted (visibility rule). The target cohort comprises all papers received in the following 182 days, all of which are observed by the cutoff (follow-up at least 2.8 years). A journal-origin was eligible if at least 100 papers were visible in the preceding 12 months and at least 50 papers were in the target cohort. The code asserts, for every journal-origin, that no target paper is visible at the origin.")
doc.add_picture(f"{ROOT}/figures/fig1_protocol_schematic.png", width=Inches(6.0)); doc.paragraphs[-1].alignment = WD_ALIGN_PARAGRAPH.CENTER
P("Figure 1. Conceptual schematic (not data) of the out-of-time protocol. Forecasts use only the visible training set; they are scored against papers submitted after the origin.", size=9.5, space=10)
P("Six forecasters of the distribution of ln D were evaluated at 19 quantile levels (0.05–0.95): F0, empirical quantiles of the last 12 months of visible papers; F1, the same over 24 months; F2, publisher-pooled quantiles that ignore journal identity (each journal weighted equally); F3, a lognormal fitted by maximum likelihood; F4, an empirical-Bayes lognormal in which journal means and log standard deviations are shrunk towards cross-journal values (DerSimonian & Laird, 1986; Efron & Morris, 1973) estimated only from visible data; F6, exponentially time-decayed empirical quantiles (half-life 182.5 days) over 24 months. F5, an interval-only forecaster, takes quantiles from the older nine months and widens them by a conformal adjustment (Angelopoulos & Bates, 2023) computed on the latest three months. Empirical quantiles use the Hazen definition (Hyndman & Fan, 1996).")
H("2.4 Scoring and inference", 2)
P("The primary score is the mean pinball loss over the 19 quantile levels on the ln-day scale (Koenker & Bassett, 1978), a proper score for quantile forecasts approximating the continuous ranked probability score (Gneiting & Raftery, 2007). Secondary scores are coverage of central 80% and 50% intervals, the Winkler interval score (Winkler, 1972), Brier scores for the events D ≤ 72, 120 and 180 days, and probability-integral-transform histograms (Gneiting et al., 2007). Journals are the unit of analysis: scores are averaged over origins within journal. Uncertainty comes from journal-cluster bootstraps (5,000 resamples for forecast comparisons, 1,000 for variance components, 2,000 for the article-level and post-hoc analyses; seed 20261020; Efron, 1979; Field & Welsh, 2007); paired comparisons use Wilcoxon signed-rank tests (Wilcoxon, 1945) with Holm correction over seven pre-specified contrasts, reported with rank-biserial effect sizes. Realised shares of papers accepted within T days carry Clopper–Pearson intervals (Clopper & Pearson, 1934).")
P(f"Variance components of ln D (journal, journal × acceptance year, residual) were estimated by method of moments from acceptance years 2021–2025 with at most 300 records per journal-year; the estimator was checked on simulated data with known components (unit tests) and intervals come from bootstrapping journals. Drift was measured as the change in a journal's median ln D between consecutive acceptance years relative to a permutation null. For RQ5, LightGBM quantile regressions (Ke et al., 2017) were trained to predict ln D from the journal's F4 quantile plus the number of authors, received month, received weekday and log references, with five-fold cross-validation grouped by journal; the comparator was the same learner without article covariates and the F4 quantile alone. Reference count is a property of the final version and is therefore only a proxy for information known at submission. Software: Python 3.13, NumPy, pandas, SciPy and LightGBM (Harris et al., 2020; Virtanen et al., 2020).")
P("Post-hoc analyses (exploratory, logged as deviations D6–D7). After internal review we (i) added a journal-cluster bootstrap for the share of journals reaching a given realised share of papers within 72 days, because the two origins of a journal are dependent; (ii) coded journals coarsely into fields by title keywords (chemistry/materials/physics, clinical medicine, engineering/computing, other; not validated); and (iii) ran a diagnostic that retrains F0 on three information sets—the visible set, the submission cohort of the preceding 12 months truncated at the origin (only papers already accepted), and an oracle submission cohort that includes papers accepted after the origin—to separate information truncation from change over time.")
P("External checks: (E8) agreement of Crossref and PubMed (History field) dates for DOIs present in both; (E9) the same forecasting protocol applied to 32 PubMed-indexed journals of publishers outside the frame (Elsevier, Oxford University Press, Frontiers, Cell Press and others), after excluding journals whose records overlap the Crossref frame. Sensitivity analyses varied the non-research filter and the eligibility thresholds (60/30).")
